<?php
defined('ABSPATH') || exit;
if (!BPM_Portal::manager()) {
    throw new RuntimeException(esc_html__('Keine Berechtigung.', 'openmieterportal'));
}
$points = BPM_Data::rows($wpdb->prepare('SELECT * FROM %i WHERE unit_id=%d ORDER BY label,id', BPM_Portal::table('meter_points'), $u->id));
$endpoint = admin_url('admin-post.php');
?>
<section class="bpm-card"><h2><?php echo esc_html__('Messstellen und Zählergeräte', 'openmieterportal'); ?></h2><p><?php echo esc_html__('Die Messstelle bleibt an der Wohnung. Jedes eingesetzte Gerät besitzt eine eigene Nummer und Gültigkeit. Ein Wechsel erhält beide Geräte und ihre Ablesungen.', 'openmieterportal'); ?></p>
<?php if (!$points) :
    ?><p><?php echo esc_html__('Noch keine Messstellen vorhanden.', 'openmieterportal'); ?></p><?php
endif; foreach ($points as $p) :
    $devices = BPM_Data::rows($wpdb->prepare('SELECT * FROM %i WHERE point_id=%d AND unit_id=%d ORDER BY installed_on DESC,id DESC', BPM_Portal::table('meters'), $p->id, $u->id));
    $open = array_values(array_filter($devices, static fn($d)=>!$d->removed_on)); ?>
<details class="bpm-thread bpm-point"><summary><?php echo  esc_html($p->label . ' · ' . $p->unit . ' · ' . count($devices) . esc_html__(' Gerät(e)', 'openmieterportal')) ?></summary>
<form method="post" action="<?php echo  esc_url($endpoint) ?>"><?php BPM_Portal::form('point_save'); ?><input type="hidden" name="unit_id" value="<?php echo  (int)$u->id ?>"><input type="hidden" name="point_id" value="<?php echo  (int)$p->id ?>">
<label><?php echo esc_html__('Bezeichnung der Messstelle', 'openmieterportal'); ?><input name="point_label" required maxlength="160" value="<?php echo  esc_attr($p->label) ?>"></label><label><?php echo esc_html__('Einheit', 'openmieterportal'); ?><select name="unit"><?php foreach (['m³','kWh',__('Einheiten', 'openmieterportal')] as $unit) :
    ?><option <?php echo  selected($p->unit, $unit, false) ?>><?php echo  esc_html($unit) ?></option><?php
       endforeach; ?></select></label><button><?php echo esc_html__('Messstelle speichern', 'openmieterportal'); ?></button></form>
<h3><?php echo esc_html__('Gerätehistorie', 'openmieterportal'); ?></h3><?php if (!$devices) :
    ?><p><?php echo esc_html__('Noch kein Gerät an dieser Messstelle.', 'openmieterportal'); ?></p><?php
    else :
        ?><div class="bpm-table-scroll"><table><thead><tr><th><?php echo esc_html__('Zählernummer', 'openmieterportal'); ?></th><th><?php echo esc_html__('Gültig ab', 'openmieterportal'); ?></th><th><?php echo esc_html__('Gültig bis', 'openmieterportal'); ?></th><th><?php echo esc_html__('Status', 'openmieterportal'); ?></th><th><?php echo esc_html__('Letzter Stand', 'openmieterportal'); ?></th></tr></thead><tbody>
        <?php foreach ($devices as $d) :
            $last = BPM_Data::row($wpdb->prepare('SELECT id,value,read_at FROM %i WHERE meter_id=%d ORDER BY read_at DESC,id DESC LIMIT 1', BPM_Portal::table('readings'), $d->id));
            $state = !$d->active ? __('Inaktiv', 'openmieterportal') : ($d->installed_on && $d->installed_on > BPM_Portal::today() ? __('Geplant', 'openmieterportal') : ($d->removed_on && $d->removed_on < BPM_Portal::today() ? __('Ausgebaut', 'openmieterportal') : ($d->removed_on ? __('Endet am ', 'openmieterportal') . $d->removed_on : __('Im Einsatz', 'openmieterportal')))); ?>
<tr><td><?php echo  esc_html($d->number) ?></td><td><?php echo  $d->installed_on ? esc_html(mysql2date('d.m.Y', $d->installed_on)) : esc_html__('Noch unbekannt', 'openmieterportal') ?></td><td><?php echo  $d->removed_on ? esc_html(mysql2date('d.m.Y', $d->removed_on)) : esc_html__('Offen', 'openmieterportal') ?></td><td><?php echo  esc_html($state) ?></td><td><?php echo  $last ? esc_html(BPM_Domain::reading_display($last->value) . ' ' . $d->unit . ' · ' . mysql2date('d.m.Y', $last->read_at)) : esc_html__('Noch keine Ablesung', 'openmieterportal') ?></td></tr>
        <?php endforeach; ?></tbody></table></div><?php
    endif; ?>
    <?php foreach ($devices as $d) :
        ?><details class="bpm-device"><summary><?php echo  esc_html(esc_html__('Gerät ', 'openmieterportal') . $d->number . ' bearbeiten') ?></summary>
<form method="post" action="<?php echo  esc_url($endpoint) ?>"><?php BPM_Portal::form('device_save'); ?><input type="hidden" name="unit_id" value="<?php echo  (int)$u->id ?>"><input type="hidden" name="point_id" value="<?php echo  (int)$p->id ?>"><input type="hidden" name="meter_id" value="<?php echo  (int)$d->id ?>">
<label><?php echo esc_html__('Zählernummer', 'openmieterportal'); ?><input name="number" required maxlength="100" value="<?php echo  esc_attr($d->number) ?>"></label><p><?php echo esc_html__( 'Messstelle:', 'openmieterportal' ); ?> <?php echo  esc_html($p->label . ' · ' . $p->unit) ?></p>
<div class="bpm-columns"><label><?php echo esc_html__('Gültig ab', 'openmieterportal'); ?><input type="date" name="installed_on" value="<?php echo  esc_attr($d->installed_on ?? '') ?>"></label><label><?php echo esc_html__('Gültig bis', 'openmieterportal'); ?><input type="date" name="removed_on" value="<?php echo  esc_attr($d->removed_on ?? '') ?>"></label></div><input type="hidden" name="active" value="0"><label class="bpm-check"><input type="checkbox" name="active" value="1" <?php echo  checked($d->active, 1, false) ?>><?php echo esc_html__('Gerät freigegeben', 'openmieterportal'); ?></label><button><?php echo esc_html__('Gerät speichern', 'openmieterportal'); ?></button></form></details><?php
    endforeach; ?>
    <?php if ($open) :
        ?><details class="bpm-exchange"><summary><?php echo esc_html__('Zählerwechsel erfassen', 'openmieterportal'); ?></summary><p><?php echo esc_html__('Der Wechsel schließt das bisherige Gerät ab und legt ein neues Gerät an derselben Messstelle an. Am Wechseltag können End- und Anfangsstand zu den jeweiligen Geräten gespeichert werden.', 'openmieterportal'); ?></p>
<form method="post" action="<?php echo  esc_url($endpoint) ?>"><?php BPM_Portal::form('device_exchange'); ?><input type="hidden" name="unit_id" value="<?php echo  (int)$u->id ?>"><input type="hidden" name="point_id" value="<?php echo  (int)$p->id ?>">
<label><?php echo esc_html__('Bisheriges Gerät', 'openmieterportal'); ?><select name="old_meter_id" required><?php foreach ($open as $d) :
    ?><option value="<?php echo  (int)$d->id ?>"><?php echo  esc_html($d->number) ?></option><?php
       endforeach; ?></select></label><label><?php echo esc_html__('Wechseldatum', 'openmieterportal'); ?><input type="date" name="change_date" required></label><label><?php echo esc_html__('Neue Zählernummer', 'openmieterportal'); ?><input name="new_number" required maxlength="100"></label>
<div class="bpm-columns"><label><?php echo esc_html__('Endstand bisheriges Gerät (optional)', 'openmieterportal'); ?><input name="end_value" inputmode="decimal" placeholder="<?php echo esc_attr__( 'z. B. 1234,567', 'openmieterportal' ); ?>"></label><label><?php echo esc_html__('Anfangsstand neues Gerät (optional)', 'openmieterportal'); ?><input name="start_value" inputmode="decimal" placeholder="<?php echo esc_attr__('Tatsächlich abgelesener Stand', 'openmieterportal'); ?>"></label></div><p class="bpm-small"><?php echo esc_html__('Ohne eingetragenen Wechselstand wird kein Zählerstand angenommen. Eine eindeutige Mietpartei zum Wechseltag erhält die zugehörige Ablesung; bei Leerstand bleibt sie nur in der Verwaltung.', 'openmieterportal'); ?></p><button><?php echo esc_html__('Zählerwechsel speichern', 'openmieterportal'); ?></button></form></details><?php
    endif; ?>
<details class="bpm-add-device"><summary><?php echo  $devices ? esc_html__('Weiteres historisches oder geplantes Gerät hinzufügen', 'openmieterportal') : esc_html__('Erstes Gerät hinzufügen', 'openmieterportal') ?></summary><form method="post" action="<?php echo  esc_url($endpoint) ?>"><?php BPM_Portal::form('device_save'); ?><input type="hidden" name="unit_id" value="<?php echo  (int)$u->id ?>"><input type="hidden" name="point_id" value="<?php echo  (int)$p->id ?>"><input type="hidden" name="meter_id" value="0"><input type="hidden" name="active" value="1"><label><?php echo esc_html__('Zählernummer', 'openmieterportal'); ?><input name="number" required maxlength="100"></label><div class="bpm-columns"><label><?php echo esc_html__('Gültig ab', 'openmieterportal'); ?><input type="date" name="installed_on" required></label><label><?php echo esc_html__('Gültig bis', 'openmieterportal'); ?><input type="date" name="removed_on"></label></div><button><?php echo esc_html__('Gerät hinzufügen', 'openmieterportal'); ?></button></form></details>
</details>
<?php endforeach; ?></section>
<section class="bpm-card"><h2><?php echo esc_html__('Neue Messstelle anlegen', 'openmieterportal'); ?></h2><form method="post" action="<?php echo  esc_url($endpoint) ?>"><?php BPM_Portal::form('point_save'); ?><input type="hidden" name="unit_id" value="<?php echo  (int)$u->id ?>"><input type="hidden" name="point_id" value="0"><label><?php echo esc_html__('Bezeichnung der Messstelle', 'openmieterportal'); ?><input name="point_label" required maxlength="160" placeholder="<?php echo esc_attr__('z. B. Kaltwasser Küche', 'openmieterportal'); ?>"></label><label><?php echo esc_html__('Einheit', 'openmieterportal'); ?><select name="unit"><option><?php echo esc_html__('m³', 'openmieterportal'); ?></option><option><?php echo esc_html__('kWh', 'openmieterportal'); ?></option><option><?php echo esc_html__('Einheiten', 'openmieterportal'); ?></option></select></label><button><?php echo esc_html__('Messstelle anlegen', 'openmieterportal'); ?></button></form></section>
